if (!items || items.length === 0) {
  return [{
    json: {
      text: "No hay datos para esa matrícula."
    }
  }];
}

const ultimo = items[items.length - 1].json;

const loc = ultimo.Loc || "";
const [lat, lon] = loc.split(",");

return [{
  json: {
    Matricula: ultimo.Matricula,
    Fecha: ultimo.Fecha,
    Veloc: ultimo.Veloc,
    Ignic: ultimo.Ignic,
    lat,
    lon,
    Loc: ultimo.Loc
  }
}];

const datos = $('Formato Datos1').first().json;

const addr = $json.address || {};

const ciudad = addr.city || addr.town || addr.village || "";
const provincia = addr.state || "";
const pais = addr.country || "";

const ubicacion = [ciudad, provincia, pais].filter(Boolean).join(", ");

const mapsUrl = `https://www.google.com/maps?q=${datos.lat},${datos.lon}`;

return [{
  json: {
    text: `🚛 ${datos.Matricula}
📍 ${ubicacion || "Dirección no encontrada"}

🗺️ ${mapsUrl}
🚗 ${datos.Veloc} km/h
🔥 ${datos.Ignic ? "encendido" : "apagado"}`
  }
}];

// Petición desde Open WebUI (webhook directo)
if ($json.body && $json.body.matricula !== undefined) {
  return [{
    json: {
      matricula: String($json.body.matricula).trim().toUpperCase().replace(/[\s-]/g, ''),
      origen: 'openwebui',
      usuario: $json.body.usuario || null,
      status: 'openwebui'
    }
  }];
}

// Petición desde Telegram (comportamiento original)
return [{
  json: {
    matricula: $('FLOTA-DIANIA').item.json.message.text.trim().toUpperCase(),
    chatId: $('FLOTA-DIANIA').item.json.message.chat.id,
    userId: $('FLOTA-DIANIA').item.json.message.from.id,
    username: $('FLOTA-DIANIA').item.json.message.from.username,
    status: $json.result.status
  }
}];


