    status: $json.result.status
  }
}];*/

// MATRÍCULA SOLICITADA (Telegram u Open WebUI)
const matricula = $('Datos MAtricula')
  .first()
  .json.matricula
  .trim()
  .toUpperCase()
  .replace(/[\s-]/g, '');

// DATOS DEVUELTOS POR MOVILDATA HORAS
const entrada = $input.all();

// Convertimos la respuesta en una lista de conductores
const datos = entrada.flatMap(item => {

  const d = item.json;

  if (Array.isArray(d)) return d;

  if (Array.isArray(d.data)) return d.data;

  if (Array.isArray(d.result)) return d.result;

  return [d];
});

// FILTRAR POR MATRÍCULA
const conductores = datos.filter(d => {

  const vehiculo = String(d.Vehiculo ?? '')
    .trim()
    .toUpperCase()
    .replace(/[\s-]/g, '');

  return vehiculo === matricula;

});

// RESULTADO
return [{
  json: {
    matricula,
    encontrado: conductores.length > 0,
    numeroConductores: conductores.length,
    conductores
  }
}];

// FORMATEAR HORAS DE CONDUCCIÓN PARA TELEGRAM

const datos = $input.first().json;

// Convierte horas decimales en horas y minutos
function formatoHoras(valor) {

  if (valor === null || valor === undefined || valor === '') {
    return 'Sin datos';
  }

  const minutos = Math.round(Number(valor) * 60);

  if (!Number.isFinite(minutos)) return 'Sin datos';

  const horas = Math.floor(minutos / 60);
  const resto = minutos % 60;

  return `${horas}h ${String(resto).padStart(2, '0')}min`;
}

// Si no encontramos conductor
if (!datos.encontrado || !datos.conductores?.length) {

  return [{
    json: {
      matricula: datos.matricula,
      mensajeHoras: '⏱ No hay información de conducción disponible.'
    }
  }];

}

// Generar información para cada conductor
const bloques = datos.conductores.map(c => {

  return `
👤 ${c.Conductor}

🚗 Conducción diaria: ${formatoHoras(c.fDiario_Horas_Real)}
⏳ Disponible diario: ${formatoHoras(c.fDiario_Resto_Real)}

🕒 Conducción sin pausa: ${formatoHoras(c.fConduccionIninterrumpida_Horas_Reales)}
☕ Restante hasta pausa: ${formatoHoras(c.fConduccionIninterrumpida_Resto_Reales)}

📅 Conducción bisemanal: ${formatoHoras(c.fBisemanal_Horas)}
📆 Disponible bisemanal: ${formatoHoras(c.fBisemanal_Resto)}
  `.trim();

});

// Resultado
return [{
  json: {
    matricula: datos.matricula,
    mensajeHoras:
      `⏱ HORAS DE CONDUCCIÓN\n\n` +
      bloques.join('\n\n━━━━━━━━━━━━\n\n')
  }
}];

